assert(!fs.existsSync(path.join(rt,'../bot.lock'))&&!fs.existsSync('STOP')&&!fs.existsSync(path.join(rt,'STOP'))&&!fs.existsSync(path.join(rt,'EXECUTION_STOP')));
const oldFile=path.join(rt,'paired-live-request.json'),old=read(oldFile);assert(Date.now()>=Date.parse(old.entryExpiresAt));
