assert(!fs.existsSync(path.join(rt,'paired-live-v2-request.json')));const archive=oldFile+'.expired-zero-order-before-generic-20261006';assert(!fs.existsSync(archive));fs.renameSync(oldFile,archive);
const universe=validateUniverse(read('live-paper/price-universe.json'),old.tournamentId),source=read('data/party-winner-no-source-screen-20261006T105231940Z.local.json');assert.equal(source.universe.hash,universe.hash);
