const startedAt=new Date().toISOString(),authority=read(path.join(rt,'paired-live-authority.json'));
const request={schemaVersion:2,mode:'one_pair_from_allowed_markets_v2',enabled:true,ownerId:'Codex',runId:'sig-pilot-paired-generic-20261006-human',tournamentId:old.tournamentId,tournamentSlug:old.tournamentSlug,universeHash:universe.hash,allowedMarkets:universe.exchanges.filter(x=>x.option==='YES').map(({marketId,exchangeId})=>({marketId,exchangeId})),startedAt,entryExpiresAt:new Date(Date.parse(startedAt)+3600000).toISOString(),authorityHash:payloadHash(authority),codeIdentity:pairedLiveV2Identity(process.cwd())};atomicJson(path.join(rt,'paired-live-v2-request.json'),request);
const sourcePlan={schemaVersion:1,owner:'Codex',id:'generic-pair-read-plan-20261006-v1',mode:'allowed_universe_pair_read_candidates',universeHash:universe.hash,createdAt:startedAt,expiresAt:new Date(Date.parse(startedAt)+1800000).toISOString(),protectedBookSlots:4,maximumAuxiliarySlots:2,rootCatalogHash:payloadHash(catalog.rootCaptures)};atomicJson(path.join(rt,'party-pair-source-plan.json'),sourcePlan);
