const evidence={schemaVersion:1,configuredAt:startedAt,retiredRun:old.runId,retiredExpiry:old.entryExpiresAt,retiredOrders:0,retiredJournalsPreserved:true,newRun:request.runId,entryExpiresAt:request.entryExpiresAt,sourceReadExpiresAt:sourcePlan.expiresAt,authorityHash:request.authorityHash,allowedMarkets:request.allowedMarkets.length,rootCaptures:catalog.rootCaptures.length,allocation:'2.000000',maxPairs:1,quantityPerLeg:1,pairCeiling:'0.990000',minimumOrdinaryMargin:'0.010000',bookSlots:{ordinary:4,auxiliary:2},extraAccountClients:0,newCredentials:0,ordersSubmitted:0};atomicJson('data/generic-paired-live-configuration-20261006.json',evidence);console.log(JSON.stringify(evidence));
